+// Till sales: each dish sold uses one portion of its recipe per qty.
+// Imports are atomic and idempotent by ticket: already-imported tickets are
+// skipped, and any missing dish or stock shortage rejects the whole batch.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** Imports validated sale lines atomically; returns { tickets, dishes }. */
+export function importSaleLines(store, lines) {
+  const dishes = store.data.dishes ?? [];
+  const existing = new Set((store.data.sales ?? []).map((s) => s.ticket));
+  const resolved = lines.map((l) => {
+    const dish = dishes.find((d) => d.id === l.dishId);
+    if (!dish) throw new AppError("bad_request", { reason: `${l.where}: unknown dish ${l.dishId}` });
+    const recipe = getRecipe(store, dish.recipeId);
+    return { ...l, needs: scaled(recipe, l.qty).filter((n) => n.qty > 0) };
+  });
+
+  const pending = resolved.filter((r) => !existing.has(r.ticket));
+  const remaining = new Map();
+  for (const r of pending) {
+    for (const n of r.needs) {
+      const item = getItem(store, n.itemId);
+      const avail = remaining.has(n.itemId) ? remaining.get(n.itemId) : onHand(store, n.itemId);
+      if (avail < n.qty) {
+        throw new AppError("not_enough_stock_row", {
+          where: r.where,
+          item: item.name,
+          available: avail,
+          unit: item.unit,
+        });
+      }
+      remaining.set(n.itemId, Math.round((avail - n.qty) * 1000) / 1000);
+    }
+  }
+
+  store.data.sales ??= [];
+  const byTicket = new Map();
+  for (const r of pending) {
+    for (const n of r.needs) consume(store, n.itemId, n.qty, { at: r.soldAt, ref: `sale:${r.ticket}` });
+    let sale = byTicket.get(r.ticket);
+    if (!sale) {
+      sale = { id: store.nextId("sale"), ticket: r.ticket, soldAt: r.soldAt, lines: [] };
+      byTicket.set(r.ticket, sale);
+      store.data.sales.push(sale);
+    }
+    sale.lines.push({ dishId: r.dishId, qty: r.qty, soldAt: r.soldAt });
+  }
+
+  return {
+    tickets: byTicket.size,
+    dishes: pending.reduce((sum, r) => sum + r.qty, 0),
+  };
+}
