+// Importing till sales from CSV (ticket,soldAt,dishId,qty).
+// Every row is checked before any stock is consumed; one bad row or shortage
+// and nothing is imported.
+import { isInstant } from "../dates.js";
+import { importSaleLines } from "../domain/sales.js";
+import { AppError } from "../errors.js";
+import { parseCsv, parseCsvObjects } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+
+function positiveInt(raw) {
+  if (!/^\d+$/.test(raw)) return null;
+  const n = Number(raw);
+  return Number.isInteger(n) && n >= 1 ? n : null;
+}
+
+/** Imports sales from CSV; returns { tickets, dishes } or throws naming the row. */
+export function importSales(store, text) {
+  const [head] = parseCsv(text);
+  const headerKeys = new Set((head ?? []).map((h) => h.trim()));
+  for (const k of HEADER) {
+    if (!headerKeys.has(k)) throw new AppError("bad_request", { reason: `missing column ${k}` });
+  }
+
+  const rows = parseCsvObjects(text);
+  const clean = rows.map((r, i) => {
+    const where = `row ${i + 2}`;
+    if (!r.ticket) throw new AppError("bad_request", { reason: `${where}: ticket is required` });
+    if (!isInstant(r.soldAt)) throw new AppError("bad_request", { reason: `${where}: bad soldAt` });
+    const dishId = positiveInt(r.dishId);
+    if (dishId === null) throw new AppError("bad_request", { reason: `${where}: bad dishId` });
+    const qty = positiveInt(r.qty);
+    if (qty === null) throw new AppError("bad_request", { reason: `${where}: bad qty` });
+    return { where, ticket: r.ticket, soldAt: new Date(r.soldAt).toISOString(), dishId, qty };
+  });
+
+  return importSaleLines(store, clean);
+}
